from lib import *
S = SS('h23')
steps = [
    step("请求和响应各带 100 KiB 数据,客户端用 UseCompressor(gzip) 与不压缩对比(代理统计线上全部字节,包括 HTTP/2 开销)。重复的 JSON 片段:请求方向 102672 → 510 字节(0.5%),响应方向 102677 → 515 字节(0.5%);类 JSON 文本:102562 → 9874 字节(9.6%);随机字节:102638 → 102593 字节(100.0%,几乎没变)。线上看到:gzip 时请求头有 grpc-encoding: gzip,每条消息 5 字节前缀的第一个字节(压缩标志位)是 1,响应也一样。压缩比取决于数据的重复程度——随机数据(比如已经压缩过的图片)压不动,白白花 CPU。", t=tl(S(1)), done=lidx(S(1), '类 JSON 文本'), mark=lidx(S(1), '重复的 JSON 片段'), b=bars([['重复片段:压缩后占原来的 %', 0.5, '0.5'], ['类 JSON 文本', 9.6, '9.6'], ['随机字节', 100.0, '100.0']], 105, mark=[0], done=[1, 2]), kv=KV([['重复的 JSON 片段', '102672 → 510 字节'], ['类 JSON 文本', '102562 → 9874 字节'], ['随机字节', '102638 → 102593 字节,不变']], ['随机字节'])),
    step("谁决定响应要不要压缩:客户端用 gzip 发请求、服务端什么都不做:请求标志位 1、响应标志位 1,响应头 grpc-encoding: gzip——服务端默认用请求用的算法回复(请求字节 628、响应字节 573)。客户端不压缩(请求标志位 0,请求字节 102562)、服务端 handler 里调用 grpc.SetSendCompressor(ctx, gzip) 并且返回 <nil>:响应标志位 1,响应字节 610。客户端的每个请求都带 grpc-accept-encoding: gzip,告诉服务端自己能解什么;SetSendCompressor 只能选客户端声明过的算法。", t=tl(S(2)), done=lidx(S(2), '客户端不压缩,服务端'), mark=lidx(S(2), '客户端 gzip,服务端不设置'), b=bars([['客户端 gzip:响应字节', 573, '573'], ['SetSendCompressor:响应字节', 610, '610'], ['SetSendCompressor:请求字节(未压缩)', 102562, '102562']], 105000, mark=[0], done=[1, 2]), kv=KV([['客户端 gzip', '响应默认也 gzip'], ['服务端 SetSendCompressor', '只压缩响应'], ['grpc-accept-encoding', '客户端声明能解的算法']], ['服务端 SetSendCompressor'])),
    step("压缩的 CPU 代价:本机回环(带宽几乎无限),往返 1 MiB 数据,各 30 次的中位数耗时。重复的 JSON 片段:不压缩 1.9 ms,gzip 3.5 ms(1.8 倍);类 JSON 文本:1.6 ms 对 8.9 ms(5.7 倍);随机字节:1.5 ms 对 2.8 ms(1.9 倍)。在回环上压缩只有成本、没有收益——它只有在网络带宽成为瓶颈时才划算(比如跨机房、移动网络)。本机的结果不能直接搬到真实网络上。", t=tl(S(3)), done=lidx(S(3), '随机字节'), mark=lidx(S(3), '类 JSON 文本'), b=bars([['类 JSON 文本:不压缩 ms', 1.6, '1.6'], ['类 JSON 文本:gzip ms', 8.9, '8.9']], 10, mark=[1], done=[0]), kv=KV([['重复片段', '1.9 → 3.5 ms'], ['类 JSON 文本', '1.6 → 8.9 ms(5.7 倍)'], ['随机字节', '1.5 → 2.8 ms']], ['类 JSON 文本'])),
    step("gzip 级别(类 JSON 文本 1 MiB):级别 1 请求 124969 字节、往返 8.9 ms;默认级别(-1)95455 字节、9.5 ms;级别 9 请求 95449 字节、31.7 ms。级别 9 只比默认省了 6 个字节,却慢了 3 倍多;级别 1 更快,但体积多 30% 左右。用 gzip.SetLevel 可以改,它是全局设置。一般不要用最高级别。", t=tl(S(4)), done=lidx(S(4), '级别  9'), mark=lidx(S(4), '级别  1'), b=bars([['级别 1 往返 ms', 8.9, '8.9'], ['默认级别往返 ms', 9.5, '9.5'], ['级别 9 往返 ms', 31.7, '31.7']], 35, mark=[2], done=[0, 1]), kv=KV([['级别 1', '124969 字节,8.9 ms'], ['默认', '95455 字节,9.5 ms'], ['级别 9', '95449 字节,31.7 ms']], ['级别 9'])),
    step("服务端不认识的压缩算法:客户端在自己的进程里注册了一个假的 “fake” 压缩器并指定使用,服务端是另一个进程:调用失败,code=Unimplemented,message=“grpc: Decompressor is not installed for grpc-encoding \"fake\"”;响应头里没有 grpc-accept-encoding(这是错误响应)。同一个连接上之后不压缩的调用 err=<nil>,不受影响。客户端不会自动退回到不压缩——指定了就得保证对方支持(可以先看对方上次响应里的 grpc-accept-encoding)。", t=tl(S(5)), done=lidx(S(5), '同一个连接上之后'), mark=lidx(S(5), '服务端不认识 fake'), b=bars([['不认识的算法:调用是否失败(1=失败)', 1, 'Unimplemented'], ['之后的不压缩调用是否失败', 0, '成功']], 1.2, mark=[0], done=[1]), kv=KV([['不认识的算法', 'Unimplemented'], ['连接', '不受影响'], ['自动降级', '没有']], ['自动降级'])),
]
A = mkarth('h23', 23, 'gRPC,压缩,gzip,UseCompressor,SetSendCompressor,grpc-encoding,Go,真实验证,动画演示',
    '实测 gRPC 的 gzip 压缩:可压缩数据线上字节只剩 0.5%~9.6%,随机数据不变;压缩标志位和 grpc-encoding;服务端 SetSendCompressor;回环上 gzip 的 CPU 代价(类 JSON 文本慢 5.7 倍);级别 9 几乎不更小;服务端不认识的算法返回 Unimplemented。',
    'gRPC 支持按消息压缩吗?怎么协商?压缩多少、花多少 CPU?这篇用本机回环测了 gzip 的体积变化和耗时变化,并看了线上的压缩标志位。',
    [('0.5% / 9.6% / 100.0%', '100 KiB 的重复片段、类 JSON 文本、随机字节经 gzip 后线上字节占原来的比例'), ('1.6 ms → 8.9 ms', '回环上往返 1 MiB 类 JSON 文本,不压缩与 gzip 的耗时'), ('Unimplemented', '服务端不认识客户端指定的压缩算法时的错误码')],
    [('怎么协商', '<p>客户端每个请求带 grpc-accept-encoding 声明能解的算法;用 UseCompressor 压缩请求时带 grpc-encoding,每条消息的 5 字节前缀里压缩标志位为 1。服务端默认用请求相同的算法回复,也可以在 handler 里用 SetSendCompressor 选一个客户端声明过的算法。</p>'),
     ('收益取决于数据', '<p>重复多的数据压到几十分之一,已经压缩的数据(随机字节)压不动,还要花 CPU。</p>'),
     ('代价', '<p>在带宽几乎无限的回环上,压缩只增加耗时;在带宽受限的网络上才可能划算,需要在真实网络上测。</p>'),
     ('级别', '<p>gzip.SetLevel 改的是全局设置。最高级别耗时数倍,体积几乎没有变化。</p>'),
     ('不认识的算法', '<p>服务端不认识就返回 Unimplemented,客户端不会自动退回到不压缩。</p>')],
    steps,
    [ENV_H + '。线上字节与压缩标志位来自抓包代理(统计两个方向的全部字节,含 HTTP/2 帧开销);耗时是本机回环上的中位数,压缩没有带宽收益,只显示 CPU 成本;“fake”压缩器只在客户端进程注册,服务端放在另一个子进程里;可压缩数据是重复的 JSON 片段,类 JSON 文本是我用代码生成的,真实数据的压缩比会不同',
     '没有验证:snappy、zstd 等其它算法(需要额外的包);真实网络(跨机房、移动网)下压缩能否缩短总时间;流式 RPC 里每条消息分别压缩的开销;WithCompressor 等已废弃的选项;服务端 CPU 占用;压缩与 TLS 结合时的安全问题(例如压缩侧信道,没有测)'],
    '压缩')
